            "CREATE TABLE verification_corrections (\n\tcorrection_id CHAR(32) NOT NULL, \n\tcycle_id CHAR(32) NOT NULL, \n\tsource_content_version_id CHAR(32) NOT NULL, \n\tcorrected_content_version_id CHAR(32) NOT NULL, \n\tcorrection_class VARCHAR(24) NOT NULL, \n\treason TEXT NOT NULL, \n\tcommand_execution_id CHAR(32) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tCONSTRAINT pk_verification_corrections PRIMARY KEY (correction_id), \n\tCONSTRAINT ck_verification_corrections_class_allowed CHECK (correction_class IN ('small','large','evidence','human_review')), \n\tCONSTRAINT ck_verification_corrections_version_changes CHECK (source_content_version_id <> corrected_content_version_id), \n\tCONSTRAINT uq_cycle_corrected_candidate UNIQUE (cycle_id, corrected_content_version_id), \n\tCONSTRAINT fk_verification_corrections_cycle_id_verification_cycles FOREIGN KEY(cycle_id) REFERENCES verification_cycles (cycle_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_verification_corrections_source_content_version_id_task_content_versions FOREIGN KEY(source_content_version_id) REFERENCES task_content_versions (content_version_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_verification_corrections_corrected_content_version_id_task_content_versions FOREIGN KEY(corrected_content_version_id) REFERENCES task_content_versions (content_version_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_verification_corrections_command_execution_id_command_executions FOREIGN KEY(command_execution_id) REFERENCES command_executions (execution_id) ON DELETE RESTRICT\n)",
